import{_ as t,c as o,o as s,aj as a}from"./chunks/framework.BlP_2-OQ.js";const u=JSON.parse('{"title":"World of Open Source Survey","description":"","frontmatter":{"title":"World of Open Source Survey","date":"2026-10-07","banner":"assets/blog/20261007_open_source_summit_banner.svg","authors":["neonephos-team"],"tags":["2026","news"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"BlogEntryThemeComponent"},"headers":[],"relativePath":"blog/20261022_open_source_summit.md","filePath":"blog/20261022_open_source_summit.md"}'),n={name:"blog/20261022_open_source_summit.md"};function r(i,e,h,c,l,p){return s(),o("div",null,e[0]||(e[0]=[a('<h1 id="neonephos-at-the-ossummit-eu" tabindex="-1">NeoNephos at the OSSummit EU! <a class="header-anchor" href="#neonephos-at-the-ossummit-eu" aria-label="Permalink to &quot;NeoNephos at the OSSummit EU!&quot;">​</a></h1><p>After a long stretch of event after event, things are finally settling down a bit which gives us a good moment to look back at the Open Source Summit Europe in Prague. It was a wonderful event. Connecting with our peers always gets our spirits up and this time was no different! The enthusiasm was especially apparent at our NeoNephos booth, where we met many new and old familiar faces, and curious and like-minded people, that gave us the chance to explain in more detail what we’re doing and where we’re heading. The booth was staffed by a strong cross-company team from a range of different NeoNephos members.</p><p>Sovereignty Requires Real Choice The highlight for NeoNephos was Tarek Becker’s keynote. As CTO of SAP’s Business AI Platform Fabric, Tarek opened with a data point: 94% of respondents to the most recent World of Open Source survey state digital sovereignty is at least somewhat important to their organization. And yet sovereignty, as he put it, must be operational – not theoretical. It requires choice. SAP runs some of the world’s most critical business processes. And the challenge they face is one many enterprises share: customers want the managed cloud experience, but they also need to keep control. Just telling someone their workload runs in the cloud doesn’t meet compliance. Sovereignty has to be real and exercisable.</p><p>Tarek walked through three NeoNephos projects that show what this looks like in practice: Gardener – a Kubernetes-native control plane that lets SAP operate thousands of clusters consistently across all major hyperscalers and their own infrastructure. One consistent interface, regardless of what’s running underneath. OVH, STACKIT, T-Systems and others already rely on it. OCM (Open Component Model) – a standardized model for packaging, describing and transporting software across environments, including air-gapped systems. It provides a Software Bill of Delivery that is signed and verifiable, which is becoming increasingly important in regulated industries. Platform Mesh – a common, declarative service management layer built on the Kubernetes resource model. It standardizes how applications consume platform services like databases across different providers, so the choice of provider stays with the customer.</p><p>These are just three of the many projects that together make sovereignty a practical reality.</p><p>Why an independent foundation matters Tarek made the case clear: single-vendor open source is not enough. Open code gives you the ability to inspect, operate and fork. Open interfaces give you the ability to build alternative implementations. But independent governance is what gives those alternatives the space to develop without requiring permission from a strategic supplier. That is why SAP donated these projects to NeoNephos under the Linux Foundation Europe – because sovereignty cannot depend on one company. SAP’s commercial interest aligns with what customers need: the best business software in the world, running on infrastructure they actually control. As Tarek closed: “Sovereignty is not the promise that you have a choice. It’s the ability to exercise it.”</p><p>Get involved If you share that goal we very much welcome you bring your projects, contribute to existing ones, or simply follow along. NeoNephos is open to everyone who wants to make choice a reality with open source.</p><p><em>Obligatory group photo and event shots:</em><img width="993" height="644" alt="image" src="https://github.com/user-attachments/assets/721bb841-3604-4d5c-b9a7-7e95e970ec4b"><img width="799" height="533" alt="1791977337928" src="https://github.com/user-attachments/assets/27764184-c531-4dfb-bd0f-50bbafb7a0e6"><img width="800" height="534" alt="1791977337471" src="https://github.com/user-attachments/assets/815a2bbe-15fc-4299-805d-b7f3249cb47f"><img width="799" height="533" alt="1791977337089" src="https://github.com/user-attachments/assets/1c926ded-0b92-4289-93dd-ce865d83b71a"></p>',8)]))}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
